package com.familyfinance.loan;
import com.familyfinance.shared.Money;
public record LoanPrepaymentResponse(long id,long transactionId,String amount,String remainingPrincipal,LoanStatus status,java.time.LocalDate paidOn,String principalAmount,String interestAmount,String cashAmount,LoanPrepaymentKind operationKind,long paymentAccountId,String scheduledRepaymentTotal,String remainingRepaymentTotal,String paidRepaymentTotal,PrepaymentStrategy strategy,Long repaymentBatchId) {
 static LoanPrepaymentResponse from(LoanPrepayment p,Loan loan,LoanTotalsService.Totals totals){return new LoanPrepaymentResponse(p.getId(),p.getTransaction().getId(),Money.formatCents(p.getAmountCents()),Money.formatCents(loan.getCurrentPrincipalCents()),loan.getStatus(),p.getPaidOn(),Money.formatCents(p.getAmountCents()),Money.formatCents(p.getInterestCents()),Money.formatCents(p.getTransaction().getAmountCents()),p.getOperationKind(),p.getTransaction().getAccount().getId(),totals.scheduledRepaymentTotal(),totals.remainingRepaymentTotal(),totals.paidRepaymentTotal(),p.getStrategy(),p.getRepaymentBatchId());}
}
